def ref(key):
    url=SOURCE_MAP[key][2]
    return f'<a href="{html.escape(url, quote=True)}">[{key}]</a>' if url.startswith("https:") else f'<span class="ref">[{key}]</span>'

def p(s, cls=""):
    return f'<p class="{cls}">{s}</p>'

def ul(items, ordered=False):
    tag="ol" if ordered else "ul"
    return f'<{tag}>'+"".join(f'<li>{x}</li>' for x in items)+f'</{tag}>'

def table(headers, rows, cls=""):
    return f'<table class="{cls}"><thead><tr>'+"".join(f'<th>{x}</th>' for x in headers)+"</tr></thead><tbody>"+"".join('<tr>'+"".join(f'<td>{x}</td>' for x in row)+"</tr>" for row in rows)+"</tbody></table>"

def note(s, cls=""):
    return f'<div class="note {cls}">{s}</div>'

def image(file, caption, height=None):
    style=f' style="max-height:{height}mm"' if height else ""
    return f'<figure><img src="{asset(file)}"{style}><figcaption>{caption}</figcaption></figure>'

