class SVG:
    def __init__(self,w=1100,h=700):
        self.w,self.h=w,h
        self.parts=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" font-family="Arial, sans-serif"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10z" fill="#126b73"/></marker></defs><rect width="100%" height="100%" fill="white"/>']
    def line(self,pts,col="#20364b",dash=False,arrow=False):
        self.parts.append(f'<polyline points="{" ".join(f"{x},{y}" for x,y in pts)}" fill="none" stroke="{col}" stroke-width="2.4"'+(' stroke-dasharray="7 5"' if dash else '')+(' marker-end="url(#arrow)"' if arrow else '')+'/>')
    def text(self,x,y,s,size=19,anchor="start",bold=False,col="#20364b"):
        for j,line in enumerate(s.split("\n")):
            self.parts.append(f'<text x="{x}" y="{y+j*(size+6)}" font-size="{size}" text-anchor="{anchor}" fill="{col}"'+(' font-weight="bold"' if bold else '')+f'>{html.escape(line)}</text>')
    def box(self,x,y,w,h,text,fill="#f0f5f9",size=20):
        self.parts.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="9" fill="{fill}" stroke="#9dabb8" stroke-width="1.4"/>')
        self.text(x+w/2,y+30,text,size,"middle",True)
    def dot(self,x,y):
        self.parts.append(f'<circle cx="{x}" cy="{y}" r="4" fill="#20364b"/>')
    def save(self,name):
        self.parts.append('</svg>')
        file=HERE/name
        file.write_text("".join(self.parts),encoding="utf-8")
        return file

